-- 메시지 삭제 (발신자 또는 수신자)
DELETE FROM messages 
WHERE senderId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com') 
   OR recipientId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 멘토 프로필 삭제
DELETE FROM mentor_profiles 
WHERE userId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 버그 리포트 삭제
DELETE FROM bug_reports 
WHERE userId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 예약 삭제
DELETE FROM bookings 
WHERE studentId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com')
   OR mentorId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 리뷰 삭제
DELETE FROM reviews 
WHERE studentId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com')
   OR mentorId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 알림 삭제
DELETE FROM notifications 
WHERE userId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 멘토 검증 정보 삭제
DELETE FROM mentor_verifications 
WHERE userId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com');

-- 멘토 갤러리 삭제
DELETE FROM mentor_gallery 
WHERE mentorId IN (SELECT id FROM mentor_profiles WHERE userId IN (SELECT id FROM users WHERE email = 'syoung.choi327@gmail.com'));

-- 사용자 계정 삭제
DELETE FROM users WHERE email = 'syoung.choi327@gmail.com';

